-- FS-UX-006: snapshot-derived procurement readiness. This migration never executes procurement.
begin;

-- Preserve the program-wide canonical priority vocabulary at the final planning
-- boundary. `required` remains represented by the separate required boolean.
alter table public.furnishing_product_selections drop constraint if exists furnishing_product_selections_priority_check;
update public.furnishing_product_selections set priority='essential' where priority='required';
alter table public.furnishing_product_selections add constraint furnishing_product_selections_priority_check check(priority in('essential','recommended','optional'));

alter table public.furnishing_procurement_baselines
  add column if not exists fsux5_handoff_id uuid references public.fsux5_procurement_handoffs(id),
  add column if not exists source_design_snapshot_id uuid references public.fsux5_approval_snapshots(id),
  add column if not exists source_budget_id uuid references public.furnishing_budgets(id),
  add column if not exists readiness_status text not null default 'draft'
    check(readiness_status in('draft','reconciling','needs_resolution','ready_for_review','in_review','changes_requested','approved','superseded','archived')),
  add column if not exists responsible_operator_id uuid references public.profiles(id),
  add column if not exists delivery_plan jsonb not null default '{}',
  add column if not exists readiness_policy_version text not null default 'fs-ux-006-v1';
alter table public.furnishing_procurement_baselines drop constraint if exists furnishing_procurement_baseline_source_check;
alter table public.furnishing_procurement_baselines add constraint furnishing_procurement_baseline_source_check check(
  (source_kind='furnishing_plan' and source_plan_id is not null and source_catalog_snapshot_id is null and fsux5_handoff_id is null and source_design_snapshot_id is null)
  or (source_kind='catalog_snapshot' and source_plan_id is null and source_catalog_snapshot_id is not null and fsux5_handoff_id is null and source_design_snapshot_id is null)
  or (source_kind='design_approval' and source_plan_id is null and source_catalog_snapshot_id is null and fsux5_handoff_id is not null and source_design_snapshot_id is not null and source_budget_id is not null)
);
create unique index if not exists fsux6_baseline_handoff_unique on public.furnishing_procurement_baselines(fsux5_handoff_id) where fsux5_handoff_id is not null;
create index if not exists fsux6_baseline_library on public.furnishing_procurement_baselines(workspace_id,readiness_status,created_at desc) where archived_at is null;

create table public.fsux6_procurement_versions(
  id uuid primary key default gen_random_uuid(), baseline_id uuid not null references public.furnishing_procurement_baselines(id), version_number integer not null check(version_number>0), based_on_version_id uuid references public.fsux6_procurement_versions(id),
  state text not null default 'reconciling' check(state in('draft','reconciling','needs_resolution','ready_for_review','in_review','changes_requested','approved','superseded','archived')),
  source_design_digest text not null, source_budget_digest text not null, policy_version text not null default 'fs-ux-006-v1', optimistic_version bigint not null default 1 check(optimistic_version>0),
  product_subtotal_minor bigint not null default 0,delivery_minor bigint not null default 0,tax_minor bigint not null default 0,assembly_minor bigint not null default 0,installation_minor bigint not null default 0,other_minor bigint not null default 0,estimated_total_minor bigint not null default 0,
  approved_budget_minor bigint not null default 0,contingency_minor bigint not null default 0,variance_minor bigint not null default 0,currency text not null check(currency ~ '^[A-Z]{3}$'),
  created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),submitted_by uuid references public.profiles(id),submitted_at timestamptz,approved_by uuid references public.profiles(id),approved_at timestamptz,archived_at timestamptz,
  unique(baseline_id,version_number)
);
alter table public.furnishing_procurement_baselines add column if not exists current_readiness_version_id uuid references public.fsux6_procurement_versions(id);

alter table public.furnishing_procurement_lines
  add column if not exists readiness_version_id uuid references public.fsux6_procurement_versions(id),
  add column if not exists product_version_id uuid references public.furnishing_product_versions(id),
  add column if not exists retailer_id uuid references public.furnishing_retailers(id),
  add column if not exists retailer_sku text,
  add column if not exists variant text,
  add column if not exists priority text not null default 'essential' check(priority in('essential','recommended','optional')),
  add column if not exists fulfillment_required boolean not null default true,
  add column if not exists baseline_unit_price_minor bigint check(baseline_unit_price_minor is null or baseline_unit_price_minor>=0),
  add column if not exists observed_unit_price_minor bigint check(observed_unit_price_minor is null or observed_unit_price_minor>=0),
  add column if not exists observed_at timestamptz,
  add column if not exists price_source text,
  add column if not exists price_freshness text not null default 'unknown' check(price_freshness in('current','stale','changed','unavailable','unknown')),
  add column if not exists availability_state text not null default 'unknown' check(availability_state in('available','limited','backordered','unavailable','discontinued','unknown','verification_stale')),
  add column if not exists delivery_minor bigint not null default 0 check(delivery_minor>=0),
  add column if not exists tax_minor bigint not null default 0 check(tax_minor>=0),
  add column if not exists assembly_minor bigint not null default 0 check(assembly_minor>=0),
  add column if not exists installation_minor bigint not null default 0 check(installation_minor>=0),
  add column if not exists fulfillment_method text not null default 'retailer_delivery',
  add column if not exists required_date date,
  add column if not exists resolution_state text not null default 'unresolved' check(resolution_state in('unresolved','ready','excluded','substitution_proposed','resolved'));
alter table public.furnishing_procurement_lines drop constraint if exists furnishing_procurement_lines_baseline_id_source_plan_line_i_key;
drop index if exists public.furnishing_procurement_plan_line_unique;
create unique index furnishing_procurement_plan_line_unique on public.furnishing_procurement_lines(baseline_id,source_plan_line_id) where source_plan_line_id is not null and readiness_version_id is null;
create unique index fsux6_procurement_version_selection_unique on public.furnishing_procurement_lines(readiness_version_id,source_plan_line_id) where readiness_version_id is not null and source_plan_line_id is not null;
create index if not exists fsux6_lines_version_retailer on public.furnishing_procurement_lines(readiness_version_id,retailer_id) where archived_at is null;

create table public.fsux6_line_allocations(
  id uuid primary key default gen_random_uuid(),readiness_version_id uuid not null references public.fsux6_procurement_versions(id),line_id uuid not null references public.furnishing_procurement_lines(id),source_selection_id uuid not null references public.furnishing_product_selections(id),room_id uuid not null references public.furnishing_rooms(id),quantity numeric(12,4) not null check(quantity>0),source_snapshot jsonb not null,created_at timestamptz not null default now(),archived_at timestamptz,
  unique(readiness_version_id,source_selection_id)
);
create table public.fsux6_retailer_groups(
  id uuid primary key default gen_random_uuid(),readiness_version_id uuid not null references public.fsux6_procurement_versions(id),retailer_id uuid references public.furnishing_retailers(id),fulfillment_method text not null default 'retailer_delivery',currency text not null check(currency ~ '^[A-Z]{3}$'),line_count integer not null default 0,unit_count numeric(12,4) not null default 0,product_subtotal_minor bigint not null default 0,delivery_minor bigint not null default 0,tax_minor bigint not null default 0,estimated_total_minor bigint not null default 0,availability_state text not null default 'unknown',readiness_state text not null default 'needs_resolution',delivery_window daterange,assumptions jsonb not null default '{}',archived_at timestamptz,
  unique nulls not distinct(readiness_version_id,retailer_id,fulfillment_method,currency)
);
create table public.fsux6_price_evidence(
  id uuid primary key default gen_random_uuid(),readiness_version_id uuid not null references public.fsux6_procurement_versions(id),line_id uuid not null references public.furnishing_procurement_lines(id),previous_unit_price_minor bigint,current_unit_price_minor bigint,currency text not null check(currency ~ '^[A-Z]{3}$'),source text not null,availability_state text not null,verified_at timestamptz not null,evidence jsonb not null default '{}',actor_id uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(readiness_version_id,idempotency_key)
);
create table public.fsux6_substitution_proposals(
  id uuid primary key default gen_random_uuid(),readiness_version_id uuid not null references public.fsux6_procurement_versions(id),line_id uuid not null references public.furnishing_procurement_lines(id),original_product_version_id uuid not null references public.furnishing_product_versions(id),replacement_product_version_id uuid not null references public.furnishing_product_versions(id),design_approved_alternative boolean not null default false,decision text not null default 'proposed' check(decision in('proposed','accepted','rejected','design_revision_required')),reason text not null,impact jsonb not null,actor_id uuid not null references public.profiles(id),decided_by uuid references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(readiness_version_id,idempotency_key),check(original_product_version_id<>replacement_product_version_id)
);
create table public.fsux6_validation_runs(
  id uuid primary key default gen_random_uuid(),readiness_version_id uuid not null references public.fsux6_procurement_versions(id),version bigint not null,policy_version text not null,issues jsonb not null,blocking_count integer not null,warning_count integer not null,informational_count integer not null,result text not null check(result in('blocked','ready')),actor_id uuid not null references public.profiles(id),correlation_id text not null,created_at timestamptz not null default now()
);
create table public.fsux6_review_events(
  id uuid primary key default gen_random_uuid(),readiness_version_id uuid not null references public.fsux6_procurement_versions(id),decision text not null check(decision in('submitted','changes_requested','approved')),reason text,actor_id uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(readiness_version_id,idempotency_key),check(decision<>'changes_requested' or length(trim(reason))>=3)
);
create table public.fsux6_readiness_snapshots(
  id uuid primary key default gen_random_uuid(),baseline_id uuid not null references public.furnishing_procurement_baselines(id),readiness_version_id uuid not null references public.fsux6_procurement_versions(id),source_design_snapshot_id uuid not null references public.fsux5_approval_snapshots(id),source_budget_id uuid not null references public.furnishing_budgets(id),snapshot jsonb not null,snapshot_digest text not null,policy_version text not null,approved_by uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(readiness_version_id),unique(baseline_id,idempotency_key)
);

create function public.fsux6_assert_actor(w uuid,reviewer boolean default false) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare a uuid:=auth.uid();r text;
begin
 if a is null then raise exception 'PROCUREMENT_ACCESS_DENIED' using errcode='42501';end if;
 r:=public.active_workspace_role(w);
 if not(public.is_admin() or r in('owner','administrator','operator')) then raise exception 'PROCUREMENT_ACCESS_DENIED' using errcode='42501';end if;
 if reviewer and not(public.is_admin() or r in('owner','administrator')) then raise exception 'PROCUREMENT_REVIEWER_REQUIRED' using errcode='42501';end if;
 perform public.assert_fs008g_procurement_mutation_enabled();return a;
end$$;

create function public.fsux6_create_project(handoff uuid,idempotency text,correlation text) returns jsonb language plpgsql security definer set search_path=public,extensions,pg_temp as $$
declare h public.fsux5_procurement_handoffs;s public.fsux5_approval_snapshots;p public.furnishing_projects;b public.furnishing_budgets;existing public.furnishing_procurement_baselines;base_id uuid;v_id uuid;a uuid;line_count integer;currency_code text;subtotal bigint;delivery_total bigint;approved_total bigint;contingency_total bigint;
begin
 if length(trim(idempotency))<8 or length(trim(correlation))<3 then raise exception 'PROCUREMENT_COMMAND_INVALID';end if;
 if auth.uid() is null then raise exception 'PROCUREMENT_ACCESS_DENIED' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(handoff::text,0));
 select * into h from public.fsux5_procurement_handoffs where id=handoff for update;if not found then raise exception 'PROCUREMENT_HANDOFF_NOT_FOUND';end if;
 select * into s from public.fsux5_approval_snapshots where id=h.approval_snapshot_id;if not found or s.id::text is distinct from h.payload->>'design_snapshot_id' then raise exception 'PROCUREMENT_SNAPSHOT_MISMATCH';end if;
 select * into p from public.furnishing_projects where id=h.project_id and design_workspace_status='approved' for update;if not found or p.id<>s.project_id or p.property_id<>s.property_id then raise exception 'PROCUREMENT_DESIGN_NOT_APPROVED';end if;
 a:=public.fsux6_assert_actor(p.workspace_id);
 select * into b from public.furnishing_budgets where id=s.budget_id and project_id=p.id and design_version_id=s.design_version_id and lifecycle_status='approved';if not found then raise exception 'PROCUREMENT_BUDGET_NOT_APPROVED';end if;
 select * into existing from public.furnishing_procurement_baselines where fsux5_handoff_id=handoff;
 if found then if existing.idempotency_key<>idempotency then raise exception 'PROCUREMENT_HANDOFF_REPLAY_CONFLICT';end if;return jsonb_build_object('project_id',existing.id,'idempotent',true,'external_effects',false);end if;
 if exists(select 1 from public.furnishing_product_selections x left join public.furnishing_products fp on fp.id=x.product_id left join public.furnishing_product_versions pv on pv.id=x.product_version_id where x.design_version_id=s.design_version_id and x.selection_role not in('excluded','existing_item_retained') and (x.product_id is null or x.product_version_id is null or fp.scope<>'workspace' or fp.workspace_id<>p.workspace_id or fp.status<>'approved' or pv.lifecycle_status<>'approved')) then raise exception 'PROCUREMENT_SOURCE_SELECTION_INELIGIBLE';end if;
 select coalesce(b.currency,'USD'),coalesce(sum(x.estimated_total_minor),0),coalesce(b.delivery_minor,0),coalesce(b.estimated_total_minor,0),coalesce(b.contingency_minor,0) into currency_code,subtotal,delivery_total,approved_total,contingency_total from public.furnishing_product_selections x where x.design_version_id=s.design_version_id group by b.currency,b.delivery_minor,b.estimated_total_minor,b.contingency_minor;
 insert into public.furnishing_procurement_baselines(workspace_id,property_id,project_id,source_kind,fsux5_handoff_id,source_design_snapshot_id,source_budget_id,source_plan_version,source_snapshot,source_hash,currency,status,readiness_status,estimated_subtotal_minor,estimated_shipping_minor,estimated_tax_minor,estimated_fees_minor,estimated_total_minor,idempotency_key,created_by,responsible_operator_id)
 values(p.workspace_id,p.property_id,p.id,'design_approval',h.id,s.id,b.id,1,jsonb_build_object('handoff',to_jsonb(h),'approval',s.snapshot),'design:'||s.snapshot_digest||':handoff:'||h.payload_digest,currency_code,'draft','reconciling',subtotal,delivery_total,b.tax_minor,b.assembly_minor+b.installation_minor,subtotal+delivery_total+b.tax_minor+b.assembly_minor+b.installation_minor,idempotency,a,a)returning id into base_id;
 insert into public.fsux6_procurement_versions(baseline_id,version_number,state,source_design_digest,source_budget_digest,product_subtotal_minor,delivery_minor,tax_minor,assembly_minor,installation_minor,estimated_total_minor,approved_budget_minor,contingency_minor,variance_minor,currency,created_by)
 values(base_id,1,'reconciling',s.snapshot_digest,encode(digest(to_jsonb(b)::text,'sha256'),'hex'),subtotal,delivery_total,b.tax_minor,b.assembly_minor,b.installation_minor,subtotal+delivery_total+b.tax_minor+b.assembly_minor+b.installation_minor,approved_total,contingency_total,subtotal+delivery_total+b.tax_minor+b.assembly_minor+b.installation_minor-approved_total,currency_code,a)returning id into v_id;
 update public.furnishing_procurement_baselines set current_readiness_version_id=v_id where id=base_id;
 insert into public.furnishing_procurement_lines(baseline_id,readiness_version_id,source_line_kind,source_plan_line_id,room_id,product_id,product_version_id,selected_offer_id,retailer_id,retailer_sku,variant,category,description,planned_quantity,existing_inventory_quantity,estimated_unit_cost_minor,estimated_line_cost_minor,baseline_unit_price_minor,observed_unit_price_minor,currency,status,priority,fulfillment_required,price_source,price_freshness,availability_state,resolution_state,source_snapshot)
 select base_id,v_id,'plan_selection',x.id,x.room_id,x.product_id,x.product_version_id,x.selected_offer_id,o.retailer_id,o.sku,coalesce(pv.product_snapshot->>'variant',''),fp.category,fp.name,x.resolved_quantity,0,x.estimated_unit_price_minor,x.estimated_total_minor,x.estimated_unit_price_minor,x.estimated_unit_price_minor,x.currency,'planned',x.priority,x.required,coalesce(x.price_source,'approved_design_snapshot'),'current',case when o.availability='in_stock' then 'available' when o.availability='low_stock' then 'limited' when o.availability='out_of_stock' then 'unavailable' else 'unknown'end,'unresolved',jsonb_build_object('designSelection',to_jsonb(x),'approvalSnapshotId',s.id)
 from public.furnishing_product_selections x join public.furnishing_products fp on fp.id=x.product_id join public.furnishing_product_versions pv on pv.id=x.product_version_id left join public.furnishing_product_offers o on o.id=x.selected_offer_id where x.design_version_id=s.design_version_id and x.selection_role not in('excluded','existing_item_retained');get diagnostics line_count=row_count;
 if line_count=0 then raise exception 'PROCUREMENT_SOURCE_HAS_NO_LINES';end if;
 insert into public.fsux6_line_allocations(readiness_version_id,line_id,source_selection_id,room_id,quantity,source_snapshot) select v_id,l.id,l.source_plan_line_id,l.room_id,l.planned_quantity,l.source_snapshot from public.furnishing_procurement_lines l where l.readiness_version_id=v_id;
 insert into public.fsux6_retailer_groups(readiness_version_id,retailer_id,currency,line_count,unit_count,product_subtotal_minor,estimated_total_minor,availability_state,readiness_state) select v_id,l.retailer_id,l.currency,count(*),sum(l.planned_quantity),sum(coalesce(l.estimated_line_cost_minor,0)),sum(coalesce(l.estimated_line_cost_minor,0)),case when bool_or(l.availability_state in('unavailable','discontinued')) then 'unavailable' when bool_or(l.availability_state='unknown') then 'unknown' else 'available'end,case when l.retailer_id is null or bool_or(l.availability_state in('unavailable','discontinued','unknown')) then 'needs_resolution' else 'ready'end from public.furnishing_procurement_lines l where l.readiness_version_id=v_id group by l.retailer_id,l.currency;
 insert into public.furnishing_procurement_events(baseline_id,workspace_id,property_id,project_id,actor_id,correlation_id,event_type,resulting_version,policy_version,related_type,related_id,payload)values(base_id,p.workspace_id,p.property_id,p.id,a,correlation::uuid,'procurement_readiness_created',1,'fs-ux-006-v1','design_snapshot',s.id,jsonb_build_object('lineCount',line_count,'noOrderPlaced',true,'externalEffects',false));
 return jsonb_build_object('project_id',base_id,'version_id',v_id,'line_count',line_count,'idempotent',false,'external_effects',false,'order_created',false);
end$$;

create function public.fsux6_validate_readiness(project uuid,expected bigint,correlation text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare base public.furnishing_procurement_baselines;v public.fsux6_procurement_versions;a uuid;issues jsonb:='[]';blocking integer:=0;warnings integer:=0;validation_id uuid;
begin
 select * into base from public.furnishing_procurement_baselines where id=project and archived_at is null for update;if not found then raise exception 'PROCUREMENT_PROJECT_NOT_FOUND';end if;a:=public.fsux6_assert_actor(base.workspace_id);
 select * into v from public.fsux6_procurement_versions where id=base.current_readiness_version_id and optimistic_version=expected and archived_at is null for update;if not found then raise exception 'PROCUREMENT_VERSION_STALE';end if;
 if exists(select 1 from public.furnishing_procurement_lines l left join public.fsux6_line_allocations a on a.line_id=l.id and a.archived_at is null where l.readiness_version_id=v.id and l.archived_at is null group by l.id having l.planned_quantity<>coalesce(sum(a.quantity),0))then issues:=issues||jsonb_build_array(jsonb_build_object('code','QUANTITY_MISMATCH','severity','blocking'));blocking:=blocking+1;end if;
 if exists(select 1 from public.furnishing_procurement_lines l where l.readiness_version_id=v.id and l.archived_at is null and l.fulfillment_required and(l.retailer_id is null or l.retailer_sku is null or l.product_version_id is null or l.availability_state in('unavailable','discontinued','unknown','verification_stale')))then issues:=issues||jsonb_build_array(jsonb_build_object('code','LINE_NOT_COMMERCIALLY_READY','severity','blocking'));blocking:=blocking+1;end if;
 if base.delivery_plan->>'address' is null or base.delivery_plan->>'receiving_contact' is null then issues:=issues||jsonb_build_array(jsonb_build_object('code','DELIVERY_PLAN_INCOMPLETE','severity','blocking'));blocking:=blocking+1;end if;
 if v.variance_minor>v.contingency_minor then issues:=issues||jsonb_build_array(jsonb_build_object('code','BUDGET_REAPPROVAL_REQUIRED','severity','blocking'));blocking:=blocking+1;end if;
 if exists(select 1 from public.furnishing_procurement_orders o where o.baseline_id=base.id and o.archived_at is null)then issues:=issues||jsonb_build_array(jsonb_build_object('code','EXTERNAL_ORDER_EXISTS','severity','blocking'));blocking:=blocking+1;end if;
 insert into public.fsux6_validation_runs(readiness_version_id,version,policy_version,issues,blocking_count,warning_count,informational_count,result,actor_id,correlation_id)values(v.id,v.optimistic_version,v.policy_version,issues,blocking,warnings,0,case when blocking=0 then 'ready' else 'blocked'end,a,correlation)returning id into validation_id;
 update public.fsux6_procurement_versions set state=case when blocking=0 then 'ready_for_review' else 'needs_resolution'end,optimistic_version=optimistic_version+1 where id=v.id;update public.furnishing_procurement_baselines set readiness_status=case when blocking=0 then 'ready_for_review' else 'needs_resolution'end where id=base.id;
 return jsonb_build_object('validation_id',validation_id,'result',case when blocking=0 then 'ready' else 'blocked'end,'blocking',blocking,'warnings',warnings,'issues',issues);
end$$;

create function public.fsux6_update_delivery_plan(project uuid,expected bigint,plan jsonb,idempotency text,correlation text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare base public.furnishing_procurement_baselines;v public.fsux6_procurement_versions;a uuid;
begin select * into base from public.furnishing_procurement_baselines where id=project and archived_at is null for update;if not found then raise exception 'PROCUREMENT_PROJECT_NOT_FOUND';end if;a:=public.fsux6_assert_actor(base.workspace_id);select * into v from public.fsux6_procurement_versions where id=base.current_readiness_version_id and optimistic_version=expected and state in('draft','reconciling','needs_resolution','changes_requested')for update;if not found then raise exception 'PROCUREMENT_VERSION_STALE';end if;if plan->>'address' is null or plan->>'receiving_contact' is null then raise exception 'PROCUREMENT_DELIVERY_PLAN_INCOMPLETE';end if;update public.furnishing_procurement_baselines set delivery_plan=plan,readiness_status='reconciling',version=version+1 where id=base.id;update public.fsux6_procurement_versions set state='reconciling',optimistic_version=optimistic_version+1 where id=v.id;return jsonb_build_object('project_id',base.id,'version_id',v.id,'idempotency_key',idempotency,'correlation_id',correlation,'external_effects',false);end$$;

create function public.fsux6_refresh_price_evidence(project uuid,line uuid,expected bigint,current_price bigint,availability text,source text,verified_at timestamptz,idempotency text,correlation text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare base public.furnishing_procurement_baselines;v public.fsux6_procurement_versions;l public.furnishing_procurement_lines;a uuid;e public.fsux6_price_evidence;delta bigint;
begin select * into base from public.furnishing_procurement_baselines where id=project and archived_at is null for update;if not found then raise exception 'PROCUREMENT_PROJECT_NOT_FOUND';end if;a:=public.fsux6_assert_actor(base.workspace_id);select * into v from public.fsux6_procurement_versions where id=base.current_readiness_version_id and optimistic_version=expected and state in('draft','reconciling','needs_resolution','changes_requested')for update;if not found then raise exception 'PROCUREMENT_VERSION_STALE';end if;select * into e from public.fsux6_price_evidence where readiness_version_id=v.id and idempotency_key=idempotency;if found then return jsonb_build_object('evidence_id',e.id,'idempotent',true);end if;if current_price<0 or availability not in('available','limited','backordered','unavailable','discontinued','unknown','verification_stale')or verified_at>now()+interval '5 minutes' then raise exception 'PROCUREMENT_PRICE_EVIDENCE_INVALID';end if;select * into l from public.furnishing_procurement_lines where id=line and readiness_version_id=v.id and archived_at is null for update;if not found then raise exception 'PROCUREMENT_LINE_NOT_FOUND';end if;insert into public.fsux6_price_evidence(readiness_version_id,line_id,previous_unit_price_minor,current_unit_price_minor,currency,source,availability_state,verified_at,actor_id,correlation_id,idempotency_key)values(v.id,l.id,l.observed_unit_price_minor,current_price,l.currency,source,availability,verified_at,a,correlation,idempotency)returning * into e;delta:=(current_price-coalesce(l.observed_unit_price_minor,l.baseline_unit_price_minor,0))*l.planned_quantity;update public.furnishing_procurement_lines set observed_unit_price_minor=current_price,observed_at=verified_at,price_source=source,price_freshness=case when current_price is distinct from baseline_unit_price_minor then 'changed' else 'current'end,availability_state=availability,resolution_state=case when availability in('available','limited')then 'ready' else 'unresolved'end,revision=revision+1 where id=l.id;update public.fsux6_procurement_versions set product_subtotal_minor=product_subtotal_minor+delta,estimated_total_minor=estimated_total_minor+delta,variance_minor=variance_minor+delta,state='reconciling',optimistic_version=optimistic_version+1 where id=v.id;update public.furnishing_procurement_baselines set estimated_subtotal_minor=estimated_subtotal_minor+delta,estimated_total_minor=estimated_total_minor+delta,readiness_status='reconciling',version=version+1 where id=base.id;return jsonb_build_object('evidence_id',e.id,'idempotent',false,'external_effects',false);end$$;

create function public.fsux6_create_revision(project uuid,expected bigint,idempotency text,correlation text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare base public.furnishing_procurement_baselines;prior public.fsux6_procurement_versions;existing public.fsux6_procurement_versions;next_id uuid;a uuid;
begin select * into base from public.furnishing_procurement_baselines where id=project and archived_at is null for update;if not found then raise exception 'PROCUREMENT_PROJECT_NOT_FOUND';end if;a:=public.fsux6_assert_actor(base.workspace_id);select * into prior from public.fsux6_procurement_versions where id=base.current_readiness_version_id and optimistic_version=expected for update;if not found then raise exception 'PROCUREMENT_VERSION_STALE';end if;if prior.state<>'approved' then raise exception 'PROCUREMENT_REVISION_SOURCE_NOT_APPROVED';end if;select * into existing from public.fsux6_procurement_versions where baseline_id=base.id and based_on_version_id=prior.id and state<>'superseded';if found then return jsonb_build_object('version_id',existing.id,'idempotent',true);end if;insert into public.fsux6_procurement_versions(baseline_id,version_number,based_on_version_id,state,source_design_digest,source_budget_digest,policy_version,product_subtotal_minor,delivery_minor,tax_minor,assembly_minor,installation_minor,other_minor,estimated_total_minor,approved_budget_minor,contingency_minor,variance_minor,currency,created_by)select baseline_id,version_number+1,id,'reconciling',source_design_digest,source_budget_digest,policy_version,product_subtotal_minor,delivery_minor,tax_minor,assembly_minor,installation_minor,other_minor,estimated_total_minor,approved_budget_minor,contingency_minor,variance_minor,currency,a from public.fsux6_procurement_versions where id=prior.id returning id into next_id;insert into public.furnishing_procurement_lines(baseline_id,readiness_version_id,source_line_kind,source_plan_line_id,room_id,product_id,product_version_id,selected_offer_id,retailer_id,retailer_sku,variant,category,description,planned_quantity,existing_inventory_quantity,estimated_unit_cost_minor,estimated_line_cost_minor,baseline_unit_price_minor,observed_unit_price_minor,observed_at,price_source,price_freshness,availability_state,delivery_minor,tax_minor,assembly_minor,installation_minor,fulfillment_method,required_date,resolution_state,currency,status,priority,fulfillment_required,source_snapshot)select baseline_id,next_id,source_line_kind,source_plan_line_id,room_id,product_id,product_version_id,selected_offer_id,retailer_id,retailer_sku,variant,category,description,planned_quantity,existing_inventory_quantity,estimated_unit_cost_minor,estimated_line_cost_minor,baseline_unit_price_minor,observed_unit_price_minor,observed_at,price_source,price_freshness,availability_state,delivery_minor,tax_minor,assembly_minor,installation_minor,fulfillment_method,required_date,resolution_state,currency,'planned',priority,fulfillment_required,source_snapshot||jsonb_build_object('copiedFromLineId',id,'revisionIdempotency',idempotency)from public.furnishing_procurement_lines where readiness_version_id=prior.id and archived_at is null;insert into public.fsux6_line_allocations(readiness_version_id,line_id,source_selection_id,room_id,quantity,source_snapshot)select next_id,n.id,n.source_plan_line_id,n.room_id,n.planned_quantity,n.source_snapshot from public.furnishing_procurement_lines n where n.readiness_version_id=next_id;insert into public.fsux6_retailer_groups(readiness_version_id,retailer_id,fulfillment_method,currency,line_count,unit_count,product_subtotal_minor,delivery_minor,tax_minor,estimated_total_minor,availability_state,readiness_state,delivery_window,assumptions)select next_id,retailer_id,fulfillment_method,currency,line_count,unit_count,product_subtotal_minor,delivery_minor,tax_minor,estimated_total_minor,availability_state,'needs_resolution',delivery_window,assumptions from public.fsux6_retailer_groups where readiness_version_id=prior.id and archived_at is null;update public.fsux6_procurement_versions set state='superseded' where id=prior.id;update public.furnishing_procurement_baselines set current_readiness_version_id=next_id,readiness_status='reconciling',status='draft',version=version+1 where id=base.id;return jsonb_build_object('version_id',next_id,'idempotent',false,'external_effects',false,'correlation_id',correlation);end$$;

create function public.fsux6_submit_review(project uuid,expected bigint,idempotency text,correlation text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare base public.furnishing_procurement_baselines;v public.fsux6_procurement_versions;a uuid;e uuid;begin select * into base from public.furnishing_procurement_baselines where id=project and archived_at is null for update;if not found then raise exception 'PROCUREMENT_PROJECT_NOT_FOUND';end if;a:=public.fsux6_assert_actor(base.workspace_id);select * into v from public.fsux6_procurement_versions where id=base.current_readiness_version_id for update;if not found then raise exception 'PROCUREMENT_VERSION_NOT_FOUND';end if;select id into e from public.fsux6_review_events where readiness_version_id=v.id and idempotency_key=idempotency;if found then return jsonb_build_object('event_id',e,'idempotent',true);end if;if v.optimistic_version<>expected then raise exception 'PROCUREMENT_VERSION_STALE';end if;if v.state<>'ready_for_review' or not exists(select 1 from public.fsux6_validation_runs x where x.readiness_version_id=v.id and x.version=expected-1 and x.result='ready' and x.created_at=(select max(y.created_at)from public.fsux6_validation_runs y where y.readiness_version_id=v.id))then raise exception 'PROCUREMENT_VALIDATION_BLOCKED';end if;insert into public.fsux6_review_events(readiness_version_id,decision,actor_id,correlation_id,idempotency_key)values(v.id,'submitted',a,correlation,idempotency)returning id into e;update public.fsux6_procurement_versions set state='in_review',submitted_by=a,submitted_at=now(),optimistic_version=optimistic_version+1 where id=v.id;update public.furnishing_procurement_baselines set readiness_status='in_review',status='under_review' where id=base.id;return jsonb_build_object('event_id',e,'idempotent',false);end$$;

create function public.fsux6_review(project uuid,expected bigint,decision text,reason text,idempotency text,correlation text) returns jsonb language plpgsql security definer set search_path=public,extensions,pg_temp as $$declare base public.furnishing_procurement_baselines;v public.fsux6_procurement_versions;a uuid;e uuid;snapshot_id uuid;s jsonb;begin select * into base from public.furnishing_procurement_baselines where id=project and archived_at is null for update;if not found then raise exception 'PROCUREMENT_PROJECT_NOT_FOUND';end if;a:=public.fsux6_assert_actor(base.workspace_id,true);select * into v from public.fsux6_procurement_versions where id=base.current_readiness_version_id for update;if not found then raise exception 'PROCUREMENT_VERSION_NOT_FOUND';end if;select id into e from public.fsux6_review_events where readiness_version_id=v.id and idempotency_key=idempotency;if found then select id into snapshot_id from public.fsux6_readiness_snapshots where readiness_version_id=v.id;return jsonb_build_object('event_id',e,'snapshot_id',snapshot_id,'idempotent',true,'order_created',false);end if;if v.optimistic_version<>expected then raise exception 'PROCUREMENT_VERSION_STALE';end if;if v.state<>'in_review' then raise exception 'PROCUREMENT_REVIEW_STATE_INVALID';end if;if decision='changes_requested' then if length(trim(reason))<3 then raise exception 'PROCUREMENT_REVIEW_REASON_REQUIRED';end if;insert into public.fsux6_review_events(readiness_version_id,decision,reason,actor_id,correlation_id,idempotency_key)values(v.id,decision,reason,a,correlation,idempotency)returning id into e;update public.fsux6_procurement_versions set state='changes_requested',optimistic_version=optimistic_version+1 where id=v.id;update public.furnishing_procurement_baselines set readiness_status='changes_requested',status='draft' where id=base.id;return jsonb_build_object('event_id',e,'idempotent',false);elsif decision<>'approved' then raise exception 'PROCUREMENT_REVIEW_DECISION_INVALID';end if;
 if not exists(select 1 from public.fsux6_validation_runs x where x.readiness_version_id=v.id and x.result='ready' order by x.created_at desc limit 1)or exists(select 1 from public.furnishing_procurement_exceptions x where x.baseline_id=base.id and x.status='open' and x.severity='blocking')then raise exception 'PROCUREMENT_VALIDATION_BLOCKED';end if;
 s:=jsonb_build_object('schemaVersion','fs-ux-006-v1','noOrderPlaced',true,'baseline',to_jsonb(base),'version',to_jsonb(v),'lines',coalesce((select jsonb_agg(to_jsonb(l)order by l.id)from public.furnishing_procurement_lines l where l.readiness_version_id=v.id and l.archived_at is null),'[]'::jsonb),'allocations',coalesce((select jsonb_agg(to_jsonb(x)order by x.id)from public.fsux6_line_allocations x where x.readiness_version_id=v.id and x.archived_at is null),'[]'::jsonb),'retailerGroups',coalesce((select jsonb_agg(to_jsonb(g)order by g.id)from public.fsux6_retailer_groups g where g.readiness_version_id=v.id and g.archived_at is null),'[]'::jsonb),'validations',coalesce((select jsonb_agg(to_jsonb(x)order by x.created_at)from public.fsux6_validation_runs x where x.readiness_version_id=v.id),'[]'::jsonb));
 insert into public.fsux6_review_events(readiness_version_id,decision,reason,actor_id,correlation_id,idempotency_key)values(v.id,'approved',reason,a,correlation,idempotency)returning id into e;insert into public.fsux6_readiness_snapshots(baseline_id,readiness_version_id,source_design_snapshot_id,source_budget_id,snapshot,snapshot_digest,policy_version,approved_by,correlation_id,idempotency_key)values(base.id,v.id,base.source_design_snapshot_id,base.source_budget_id,s,encode(digest(s::text,'sha256'),'hex'),v.policy_version,a,correlation,idempotency)returning id into snapshot_id;update public.fsux6_procurement_versions set state='approved',approved_by=a,approved_at=now(),optimistic_version=optimistic_version+1 where id=v.id;update public.furnishing_procurement_baselines set readiness_status='approved',status='under_review' where id=base.id;return jsonb_build_object('event_id',e,'snapshot_id',snapshot_id,'idempotent',false,'external_effects',false,'order_created',false,'purchase_authorized',false);end$$;

create function public.fsux6_prevent_snapshot_mutation() returns trigger language plpgsql set search_path=public,pg_temp as $$begin raise exception 'PROCUREMENT_READINESS_SNAPSHOT_IMMUTABLE';end$$;
create trigger fsux6_snapshot_immutable before update or delete on public.fsux6_readiness_snapshots for each row execute function public.fsux6_prevent_snapshot_mutation();

-- Extend the frozen controlled-cleanup boundary. Mutable readiness projections are
-- archived before the predecessor cleanup runs; immutable evidence remains retained.
alter table public.fsux6_substitution_proposals add column if not exists archived_at timestamptz;
create table public.fsux6_cleanup_manifests(
 id uuid primary key default gen_random_uuid(),designation_id uuid not null unique references public.furnishing_controlled_fixture_designations(id),project_id uuid not null references public.furnishing_projects(id),manifest jsonb not null,cleanup_run_id uuid references public.furnishing_cleanup_runs(id),created_at timestamptz not null default now()
);
alter function public.cleanup_fs008g_synthetic_project(jsonb) rename to cleanup_fs008g_synthetic_project_pre_fsux6;
create function public.cleanup_fs008g_synthetic_project(p_input jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare designation uuid;project uuid;prior public.fsux6_cleanup_manifests;before_counts jsonb;predecessor jsonb;run_id uuid;active_count integer;
begin
 if auth.role()<>'service_role' then raise exception 'FS008G_FIXTURE_SERVICE_ROLE_REQUIRED' using errcode='42501';end if;
 begin designation:=(p_input->>'designation_id')::uuid;project:=(p_input->>'project_id')::uuid;exception when others then raise exception 'CLEANUP_COMMAND_INVALID';end;
 select * into prior from public.fsux6_cleanup_manifests where designation_id=designation;
 if found then predecessor:=public.cleanup_fs008g_synthetic_project_pre_fsux6(p_input);return jsonb_build_object('status','already_cleaned','id',prior.cleanup_run_id,'designationId',designation,'reconciliation',(predecessor->'reconciliation')||jsonb_build_object('fsux6',prior.manifest));end if;
 perform 1 from public.furnishing_controlled_fixture_designations d where d.id=designation and d.project_id=project and d.cleaned_at is null and d.revoked_at is null and d.expires_at>now() for update;if not found then raise exception 'CLEANUP_DESIGNATION_INVALID';end if;
 perform 1 from public.furnishing_projects where id=project for update;
 perform 1 from public.furnishing_procurement_baselines where project_id=project and archived_at is null for update;
 perform 1 from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project and v.archived_at is null for update of v;
 perform 1 from public.fsux6_line_allocations a join public.fsux6_procurement_versions v on v.id=a.readiness_version_id join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project and a.archived_at is null for update of a;
 perform 1 from public.fsux6_retailer_groups g join public.fsux6_procurement_versions v on v.id=g.readiness_version_id join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project and g.archived_at is null for update of g;
 perform 1 from public.fsux6_substitution_proposals s join public.fsux6_procurement_versions v on v.id=s.readiness_version_id join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project and s.archived_at is null for update of s;
 perform public.assert_fs008g_cleanup_dependencies(designation,true);
 select jsonb_build_object('versions',(select count(*) from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project and v.archived_at is null),'allocations',(select count(*) from public.fsux6_line_allocations a join public.fsux6_procurement_versions v on v.id=a.readiness_version_id join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project and a.archived_at is null),'retailerGroups',(select count(*) from public.fsux6_retailer_groups g join public.fsux6_procurement_versions v on v.id=g.readiness_version_id join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project and g.archived_at is null),'substitutions',(select count(*) from public.fsux6_substitution_proposals s join public.fsux6_procurement_versions v on v.id=s.readiness_version_id join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project and s.archived_at is null),'retainedPriceEvidence',(select count(*) from public.fsux6_price_evidence e join public.fsux6_procurement_versions v on v.id=e.readiness_version_id join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project),'retainedValidations',(select count(*) from public.fsux6_validation_runs x join public.fsux6_procurement_versions v on v.id=x.readiness_version_id join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project),'retainedReviews',(select count(*) from public.fsux6_review_events e join public.fsux6_procurement_versions v on v.id=e.readiness_version_id join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project),'retainedReadinessSnapshots',(select count(*) from public.fsux6_readiness_snapshots s where s.baseline_id in(select id from public.furnishing_procurement_baselines where project_id=project))) into before_counts;
 update public.fsux6_line_allocations set archived_at=now() where readiness_version_id in(select v.id from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project)and archived_at is null;
 update public.fsux6_retailer_groups set archived_at=now() where readiness_version_id in(select v.id from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project)and archived_at is null;
 update public.fsux6_substitution_proposals set archived_at=now() where readiness_version_id in(select v.id from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project)and archived_at is null;
 update public.fsux6_procurement_versions set state='archived',archived_at=now() where baseline_id in(select id from public.furnishing_procurement_baselines where project_id=project)and archived_at is null;
 select count(*) into active_count from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where b.project_id=project and v.archived_at is null;if active_count<>0 then raise exception 'CLEANUP_RECONCILIATION_FAILED';end if;
 predecessor:=public.cleanup_fs008g_synthetic_project_pre_fsux6(p_input);run_id:=(predecessor->>'id')::uuid;
 insert into public.fsux6_cleanup_manifests(designation_id,project_id,manifest,cleanup_run_id)values(designation,project,before_counts||jsonb_build_object('activeVersions',active_count),run_id)returning * into prior;
 return jsonb_build_object('status','clean','id',run_id,'designationId',designation,'reconciliation',(predecessor->'reconciliation')||jsonb_build_object('fsux6',prior.manifest));
end$$;

alter table public.fsux6_procurement_versions enable row level security;
alter table public.fsux6_line_allocations enable row level security;
alter table public.fsux6_retailer_groups enable row level security;
alter table public.fsux6_price_evidence enable row level security;
alter table public.fsux6_substitution_proposals enable row level security;
alter table public.fsux6_validation_runs enable row level security;
alter table public.fsux6_review_events enable row level security;
alter table public.fsux6_readiness_snapshots enable row level security;
alter table public.fsux6_cleanup_manifests enable row level security;
create policy "Workspace members read procurement versions" on public.fsux6_procurement_versions for select to authenticated using(exists(select 1 from public.furnishing_procurement_baselines b where b.id=baseline_id and(public.active_workspace_role(b.workspace_id)is not null or public.is_admin())));
create policy "Workspace members read line allocations" on public.fsux6_line_allocations for select to authenticated using(exists(select 1 from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where v.id=readiness_version_id and(public.active_workspace_role(b.workspace_id)is not null or public.is_admin())));
create policy "Workspace members read retailer groups" on public.fsux6_retailer_groups for select to authenticated using(exists(select 1 from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where v.id=readiness_version_id and(public.active_workspace_role(b.workspace_id)is not null or public.is_admin())));
create policy "Workspace members read price evidence" on public.fsux6_price_evidence for select to authenticated using(exists(select 1 from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where v.id=readiness_version_id and(public.active_workspace_role(b.workspace_id)is not null or public.is_admin())));
create policy "Workspace members read substitutions" on public.fsux6_substitution_proposals for select to authenticated using(exists(select 1 from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where v.id=readiness_version_id and(public.active_workspace_role(b.workspace_id)is not null or public.is_admin())));
create policy "Workspace members read validations" on public.fsux6_validation_runs for select to authenticated using(exists(select 1 from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where v.id=readiness_version_id and(public.active_workspace_role(b.workspace_id)is not null or public.is_admin())));
create policy "Workspace members read reviews" on public.fsux6_review_events for select to authenticated using(exists(select 1 from public.fsux6_procurement_versions v join public.furnishing_procurement_baselines b on b.id=v.baseline_id where v.id=readiness_version_id and(public.active_workspace_role(b.workspace_id)is not null or public.is_admin())));
create policy "Workspace members read readiness snapshots" on public.fsux6_readiness_snapshots for select to authenticated using(exists(select 1 from public.furnishing_procurement_baselines b where b.id=baseline_id and(public.active_workspace_role(b.workspace_id)is not null or public.is_admin())));
create policy "Admins read cleanup manifests" on public.fsux6_cleanup_manifests for select to authenticated using(public.is_admin() and exists(select 1 from public.furnishing_projects p where p.id=project_id and public.active_workspace_role(p.workspace_id)is not null));

revoke all on public.fsux6_procurement_versions,public.fsux6_line_allocations,public.fsux6_retailer_groups,public.fsux6_price_evidence,public.fsux6_substitution_proposals,public.fsux6_validation_runs,public.fsux6_review_events,public.fsux6_readiness_snapshots from public,anon,authenticated;
grant select on public.fsux6_procurement_versions,public.fsux6_line_allocations,public.fsux6_retailer_groups,public.fsux6_price_evidence,public.fsux6_substitution_proposals,public.fsux6_validation_runs,public.fsux6_review_events,public.fsux6_readiness_snapshots to authenticated;
revoke all on public.fsux6_cleanup_manifests from public,anon,authenticated;grant select on public.fsux6_cleanup_manifests to authenticated;
